INSERT INTO @meta (OrgId,Website,ProfileNote) VALUES
(19147, N'https://danesharchs.com', N'AIBC-registered architectural firm based in Vancouver, BC. Sole principal Alireza Danesh holds AIBC, AIA, NCARB, and MRAIC credentials with background in residential architecture and urban design. Website is under active reconstruction with no portfolio publicly accessible.'),
(26979, N'https://jywarchitecture.com', N'Vancouver BC architecture firm founded by Joe Y. Wai (1978), reincorporated 2016 under Principal Wan Qi. Specializes in social/affordable housing, residential care facilities, heritage restoration, and community/cultural projects exclusively in BC, with deep roots in Vancouver Chinatown and the Downtown Eastside.'),
(19095, N'https://radiant-city.com/', N'Vancouver BC small studio (est. 1994 as Division Zero Architecture) at #222-1118 Homer St. Focus on residential, mixed-use, and tenant improvement projects across Greater Vancouver and the Lower Mainland.'),
(20197, N'https://www.salikanarchitecture.ca/', N'Vancouver BC full-service studio founded 1988 at #923-409 Granville St. Specializes in commercial, institutional, recreational, and residential buildings; operates in BC and Alberta with past projects in the USA and Japan.'),
(23375, N'https://www.tkad.ca/', N'TKA+D is a Vancouver BC architecture and interior design practice (est. 2008) with 5 principals and approximately 40 staff. Works across commercial, industrial, institutional, and residential sectors in Greater Vancouver and Australia. Operating name TKA+D.'),
(23845, N'https://alabasterhomes.ca/', N'Boutique Vancouver BC residential developer (est. 2014) building single-family, multiplex, and rental projects across Vancouver neighbourhoods (Oakridge, Marpole, etc.). Emphasises design-driven construction and integrated post-occupancy homeowner services.'),
(23957, N'https://arborlea.ca', N'Surrey/Langley BC general contractor (est. 1986) specializing in tenant improvements for dental, medical, professional, and retail interiors across Greater Vancouver. Operates as a contractor/project manager, not a residential or commercial real estate developer.'),
(32155, N'https://www.bogner.ca', N'Bogner Kerrisdale Development Inc. is a project-specific subsidiary of Bogner Development Group Ltd. (Richmond BC, est. 1970s), a boutique residential developer building luxury low-to-mid-rise condos and townhomes across Vancouver west side and Surrey. The Kerrisdale entity corresponds to The Kirkland at 6168 East Blvd.'),
(22200, N'https://www.bucci.com', N'Bucci Garden Homes Ltd is a BC-registered project entity of Bucci Developments Ltd (Suite 202, 1669 West 3rd Ave, Vancouver BC), a third-generation family developer building mid-density residential condos and rentals across Western Canada. The entity is named for the 2550 Garden Drive project in East Vancouver.'),
(28435, N'https://catalystcommdev.org', N'Vancouver-based BC non-profit developer (309-877 East Hastings St, Vancouver BC V6A 3Y1) building purpose-built below-market rental housing across the Lower Mainland and Victoria. Partners with community organizations to unlock land value for affordable housing at 89-203 unit scale.'),
(38201, N'https://deecorp.ca/', N'Vancouver commercial real estate developer founded 1994 by Stanley Dee; $600M+ portfolio of retail, mixed-use, and hotel assets across BC. Currently advancing three 33-storey hotel towers totalling ~1,000 rooms in downtown Vancouver.'),
(20891, N'http://www.enticecreations.com', N'Burnaby, BC custom home builder and residential developer; HAVAN member since 2018. Office at 4556 Dawson Street, Burnaby BC V5C 4C1. Related entity Entice Building Materials Ltd (kitchen/bath supply) operates at the same address.'),
(21675, N'https://greenoakdevelopment.com', N'Vancouver BC luxury residential developer founded 2016; specializes in luxury estates, mixed-use, and multi-family projects on Vancouver''s West Side. Known for European/Italian design aesthetic with imported Italian finishes. Office at 4445 West 10th Ave, Vancouver BC V6R 2H8.'),
(20756, NULL, N'BC-registered developer and contractor incorporated 2013-05-04 in Delta, BC (BC Corp No. 0969245); formerly LHL Enterprises Ltd, renamed April 2016. Held City of Vancouver contractor licences 2016-2019; consistent with small infill or custom residential work in Greater Vancouver.'),
(51663, N'https://icegoc.com', N'ICE Group of Companies (legal: ICE Development Ltd), a Langley BC integrated design-build and development firm founded 2004. Operates across BC on multi-family residential, commercial, industrial, and municipal projects; ~10-50 employees. General contact: info@icegoc.com, 604-381-2202.'),
(22051, N'https://kutakdevelopment.com/', N'Vancouver BC real estate developer founded ~2015; provides full-scope services from acquisition through permitting, construction, and sales. Active in Metro Vancouver and Tri-Cities with multi-unit residential condo and rental projects.'),
(20518, NULL, N'Vancouver residential developer; formerly Matchpoint Development Ltd (name changed Feb 2019). Completed Chloe at 2096 W 47th Ave, Kerrisdale (46 strata + 11 retail units, 2024). Placed under receivership Feb 2025 (FTI Consulting appointed) due to liquidity crisis; company appears dormant.'),
(22259, N'https://livingspacehomes.com', N'Vancouver BC full-service residential developer and interior design firm founded 2013. Provides turn-key home building from site selection and permitting through construction management and European interior fit-out. Office: 120-1706 West 1st Ave, Vancouver BC V6J 0E4. General contact: info@livingspacehomes.com.'),
(24020, N'https://petersonbc.com', N'Development-arm entity of The Peterson Group, a major Vancouver family-owned developer founded 1959 by Peter Young. Headquartered at 1166 Alberni St, Vancouver. Portfolio of 23M+ sq ft spanning mixed-use residential, commercial, and hospitality across BC and North America.'),
(32397, NULL, N'BC developer incorporated as 1011180 B.C. Ltd., renamed Raichu Cambie Development Ltd. on 2018-07-09. Single-project vehicle for Winona on Cambie (7638 Cambie St, Vancouver), a 38-unit 6-storey condo completed ~2021 in the Cambie Corridor. Affiliated with Raichu Development Group, Surrey BC.'),
(21389, N'https://solarisproperties.ca/', N'Vancouver BC custom home builder and renovator operating since 1999; specializes in custom homes, full renovations, and house lifting in Metro Vancouver''s west side. Not a large-scale condo/strata developer. General contact: info@solarisproperties.ca.'),
(19717, N'https://www.terrablanka.com', N'Vancouver BC boutique developer founded 2013; specializes in luxury residential townhomes and multi-family projects on Vancouver''s West Side. Three completed/active projects in South Cambie and Oakridge. Office: 1281 W Georgia St, Vancouver BC. General contact: info@terrablanka.com.'),
(21798, N'https://tyko.ca', N'Vancouver-based fully integrated real estate developer and general contractor founded 2011, specializing in custom homes, laneway/coach homes, ADUs, and mixed-use commercial/residential development across the Lower Mainland.'),
(43596, N'https://www.bostonconstructioncorp.com', N'Surrey, BC general contractor founded 2005 (DBA Boston Builders Group), providing restoration, construction management, design-build, and new construction services across the Lower Mainland for residential, commercial, and municipal clients. Not related to any Massachusetts entity.'),
(49490, N'https://www.dawsonconstruction.ca/', N'Kamloops-based BC heavy civil contractor founded 1922; specializes in highway construction, paving, and aggregate supply across BC and Alberta. Part of the family-owned Dawson Group; one of four founding members of the BC Road Builders and Heavy Construction Association (1964).'),
(22060, N'https://gocancontracting.com', N'Richmond, BC-based general contractor providing commercial tenant improvements and residential construction across Greater Vancouver for 10+ years; specializes in retail TI, custom millwork, and design-build for shopping-centre and office clients.'),
(30335, N'https://jerichogeneralcontractors.com', N'Vancouver-based commercial general contractor (est. 2017) specializing in tenant improvements, building restoration, and design-build for offices, medical/dental clinics, churches, restaurants, and multifamily/strata buildings across Metro Vancouver.'),
(24124, N'https://www.lionsheadconstruction.com', N'Vancouver-based full-service commercial and residential general contractor founded 1996, specializing in dental and medical office construction and renovation across BC; 60+ professionals and sub-contractors with a niche in custom millwork and tenant improvement.'),
(12633, N'https://novacom.ca/', N'Surrey, BC-based construction manager and general contractor (DBA Novacom Building Partners) founded 1991. Specializes in tenant improvements, design-build, and construction management for commercial, institutional, and mixed-use projects across BC and Alberta.'),
(28554, N'https://weareperformance.ca', N'Richmond, BC general contractor (est. 2007, operating as Performance Builders Ltd.) specializing in multi-family market housing, social housing, and mixed-use design-build across Metro Vancouver; 65+ completed housing projects.'),
(19205, N'https://prismconstruction.ca', N'Delta, BC commercial and industrial general contractor founded 1998 by Amin Rawji. Specializes in design-build for self-storage, auto showrooms, warehouses, food processing, and film studio facilities; 600+ projects, 20M sq ft, $2B+ in construction value.'),
(19893, N'https://proformconstruction.ca', N'Small Burnaby, BC-incorporated general contractor (3 FTE) based at 3912 Spruce St, Burnaby; serves the Lower Mainland on residential and commercial design-build including condos, restaurants, and custom homes.'),
(20869, N'https://www.summitbrooke.com', N'Abbotsford, BC privately owned commercial general contractor founded 1998 (incorporated as Summit Brooke Development Corp). Specializes in multi-family townhomes, industrial tilt-up, corporate roll-outs, and tenant improvements throughout BC; COR certified with ~45-69 employees.'),
(22624, N'https://www.truemaple.com', N'Vancouver-based licensed general contractor and custom home builder incorporated December 2016, specializing in architect-designed custom homes, laneway homes, and residential renovations across 21 Lower Mainland municipalities. HAVAN member.');
